package org.apache.commons.lang;

import java.io.*;
import java.io.IOException;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Entities_unescape_TriageGen2Test {

    private Entities entities;

    @Before
    public void setUp() {
        entities = new Entities();
        // Adding some standard entities for testing purposes
        entities.addEntity("lt", '<');
        entities.addEntity("gt", '>');
        entities.addEntity("amp", '&');
    }

    @Test
    public void testUnescape_NoAmpersand() {
        assertEquals("hello", entities.unescape("hello"));
        assertEquals("", entities.unescape(""));
    }

    @Test
    public void testUnescape_SingleAmpersandNoSemi() {
        assertEquals("a&b", entities.unescape("a&b"));
    }

    @Test
    public void testUnescape_AmpersandNoSemiBetweenAmpersands() {
        // Tests the logic: if (amph != -1 && amph < semi)
        assertEquals("&amp;", entities.unescape("&amp;")); 
        // Wait, the logic says if amph < semi, it appends '&' and continues.
        // In "&amp;", semi is 4. There is no second '&'. 
        // Let's try "&a&b;" -> first '&' at 0. next '&' at 2. semi for first '&' is 5.
        // Since 2 < 5, it appends '&' and continues loop from i=0.
        assertEquals("&a&b;", entities.unescape("&a&b;"));
    }

    @Test
    public void testUnescape_EntityNameEmpty() {
        assertEquals(";&", entities.unescape("&;"));
    }

    @Test
    public void testUnescape_DecimalEntity() {
        assertEquals("<", entities.unescape("&#60;"));
        assertEquals(" ", entities.unescape("&#32;"));
    }

    @Test
    public void testUnescape_HexEntityLower() {
        assertEquals("<", entities.unescape("&#x3c;"));
    }

    @Test
    public void testUnescape_HexEntityUpper() {
        assertEquals("<", entities.unescape("&#X3C;"));
    }

    @Test
    public void testUnescape_InvalidDecimalEntity() {
        // entityName.length == 1 (just '#')
        assertEquals("&#", entities.unescape("&#"));
        // NumberFormatException
        assertEquals("&abc;", entities.unescape("&#abc;"));
    }

    @Test
    public void testUnescape_InvalidHexEntity() {
        // NumberFormatException in hex
        assertEquals("&xZZ;", entities.unescape("&#xZZ;"));
    }

    @Test
    public void testUnescape_NamedEntity() {
        assertEquals("<", entities.unescape("&lt;"));
        assertEquals(">", entities.unescape("&gt;"));
    }

    @Test
    public void testUnescape_UnknownNamedEntity() {
        assertEquals("&unknown;", entities.unescape("&unknown;"));
    }

    @Test
    public void testUnescape_MixedContent() {
        assertEquals("a < b & c > d", entities.unescape("a &lt; b &amp; c &gt; d"));
    }

    @Test
    public void testUnescape_ComplexEdgeCases() {
        // Test case where semi is -1
        assertEquals("a&b", entities.unescape("a&b"));

        // Test case where entityValue is -1 due to logic
        // &; -> entityName is "" -> entityValue = -1 -> returns "&;"
        assertEquals("&;", entities.unescape("&;"));

        // Test case where entityValue is -1 due to length 1
        // &#; -> entityName is "#" -> entityValue = -1 -> returns "&#;"
        assertEquals("&#;", entities.unescape("&#;"));

        // Test case: &...&...;
        // index 0 is '&'. next '&' is at 2. ';' is at 5. 
        // 2 < 5 is true. Append '&', loop continues at i=0 (actually loop i increments).
        // This specific logic in the provided code is a bit unusual, 
        // it appends '&' and continues the loop.
        assertEquals("&a&b;", entities.unescape("&a&b;"));
    }

    @Test
    public void testUnescape_LargeInteger() {
        // Testing potential overflow or large values if applicable, 
        // but Integer.valueOf handles standard ranges.
        assertEquals("\u007F", entities.unescape("&#127;"));
    }
}
